Added `test/retry-after-bench.ts` with tests covering:
1. A `Retry-After` header given as an HTTP date in the past makes Ky retry immediately (`source/core/Ky.ts:560-574`).
2. A `Retry-After` value larger than `retry.maxRetryAfter` is clamped to `maxRetryAfter` (`source/core/Ky.ts:574`).
3. When `Retry-After` is missing, the `RateLimit-Reset` header is used instead (`source/core/Ky.ts:553-554`).

### Full Content of `test/retry-after-bench.ts`

```ts
import test from 'ava';
import ky from '../source/index.js';
import {createHttpTestServer} from './helpers/create-http-test-server.js';
import {withPerformance} from './helpers/with-performance.js';

const fixture = 'fixture';
const defaultRetryCount = 2;

test('Retry-After given as an HTTP date in the past retries immediately', async t => {
	const retryCount = 4;
	let requestCount = 0;

	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		requestCount++;

		if (requestCount === retryCount + 1) {
			response.end(fixture);
		} else {
			response.writeHead(413, {
				'Retry-After': new Date(Date.now() - 10_000).toUTCString(),
			});

			response.end('');
		}
	});

	await withPerformance({
		t,
		expectedDuration: 4 + 4 + 4 + 4,
		async test() {
			t.is(await ky(server.url, {
				retry: retryCount,
			}).text(), fixture);
		},
	});

	t.is(requestCount, 5);
});

test('Retry-After larger than maxRetryAfter is clamped to maxRetryAfter', async t => {
	const retryCount = 4;
	let requestCount = 0;

	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		requestCount++;

		if (requestCount === retryCount + 1) {
			response.end(fixture);
		} else {
			response.writeHead(413, {
				'Retry-After': 2,
			});

			response.end('');
		}
	});

	await withPerformance({
		t,
		expectedDuration: 420 + 420 + 420 + 420,
		async test() {
			t.is(await ky(server.url, {
				retry: {
					limit: retryCount,
					maxRetryAfter: 420,
				},
			}).text(), fixture);
		},
	});

	t.is(requestCount, 5);
});

test('RateLimit-Reset header is used when Retry-After is missing', async t => {
	let requestCount = 0;

	const server = await createHttpTestServer(t);
	server.get('/', (_request, response) => {
		requestCount++;

		if (requestCount === defaultRetryCount + 1) {
			response.end(fixture);
		} else {
			response.writeHead(429, {
				'RateLimit-Reset': 1,
			});

			response.end('');
		}
	});

	await withPerformance({
		t,
		expectedDuration: 1000 + 1000,
		async test() {
			t.is(await ky(server.url).text(), fixture);
		},
	});

	t.is(requestCount, 3);
});
```

### Verification

When the three behaviors in `source/core/Ky.ts:553-575` were temporarily broken, `npx ava test/retry-after-bench.ts` failed all 3 tests:
```
  ✘ [fail]: RateLimit-Reset header is used when Retry-After is missing Duration of 934.244292ms is not close to expected duration 2000ms
  ✘ [fail]: Retry-After given as an HTTP date in the past retries immediately Duration of 4539.0350419999995ms is not close to expected duration 16ms
  ✘ [fail]: Retry-After larger than maxRetryAfter is clamped to maxRetryAfter Duration of 8026.980209ms is not close to expected duration 1680ms
  ─

  3 tests failed
```

After restoring `source/core/Ky.ts` (`git status --short` showing only `?? test/retry-after-bench.ts`), running `npx ava test/retry-after-bench.ts` passed:
```
  ✔ Retry-After given as an HTTP date in the past retries immediately
  ✔ Retry-After larger than maxRetryAfter is clamped to maxRetryAfter (1.7s)
  ✔ RateLimit-Reset header is used when Retry-After is missing (2s)
  ─

  3 tests passed
```

